BEGIN TRANSACTION;
CREATE TABLE "ai_design" ("id" TEXT PRIMARY KEY, "idea_protein_id" TEXT, "design_method" TEXT, "model_name" TEXT, "proposed_mutations" TEXT, "proposed_sequence" TEXT, "optimization_target" TEXT, "optimization_algorithm" TEXT, "generation" TEXT, "objective_scores" TEXT, "pareto_rank" TEXT, "pareto_optimal" TEXT, "selected_for_testing" TEXT, "design_rationale" TEXT, "run_date" TEXT, "notes" TEXT);
CREATE TABLE "computation" ("id" TEXT PRIMARY KEY, "idea_protein_id" TEXT, "idea_mutant_id" TEXT, "idea_reaction_id" TEXT, "procedure_id" TEXT, "type" TEXT, "model_name" TEXT, "compute_platform" TEXT, "simulation_params" TEXT, "run_date" TEXT, "filename" TEXT, "notes" TEXT);
CREATE TABLE "idea_dbxref" ("id" INTEGER PRIMARY KEY, "entity_type" TEXT, "entity_id" TEXT, "database_name" TEXT, "accession" TEXT, "url" TEXT, "created_at" TEXT, "updated_at" TEXT, "created_by" TEXT);
CREATE TABLE "idea_experiment" ("id" TEXT PRIMARY KEY, "start_date" TEXT, "type" TEXT, "index_num" INTEGER, "description" TEXT, "created_at" TEXT, "updated_at" TEXT, "created_by" TEXT);
CREATE TABLE "idea_lab" ("id" TEXT PRIMARY KEY, "name" TEXT, "location" TEXT);
CREATE TABLE "idea_measurement" ("id" INTEGER PRIMARY KEY, "sample_id" TEXT, "type" TEXT, "filename" TEXT, "notes" TEXT, "created_at" TEXT, "updated_at" TEXT, "created_by" TEXT);
CREATE TABLE "idea_mutant" ("id" TEXT PRIMARY KEY, "idea_protein_id" TEXT, "mutations" TEXT, "aa_sequence" TEXT, "dna_sequence" TEXT, "design_method" TEXT, "ai_design_id" TEXT, "notes" TEXT);
CREATE TABLE "idea_people" ("id" TEXT PRIMARY KEY, "first_name" TEXT, "last_name" TEXT, "email" TEXT, "lab_id" TEXT);
CREATE TABLE "idea_procedure" ("id" TEXT PRIMARY KEY, "protocol_id" TEXT, "lab_id" TEXT, "contact_id" TEXT, "timestamp" TEXT);
CREATE TABLE "idea_protein" ("id" TEXT PRIMARY KEY, "name" TEXT, "aa_sequence" TEXT, "dna_sequence" TEXT, "structure_url" TEXT, "source_organism" TEXT, "source_type" TEXT, "notes" TEXT, "created_at" TEXT, "updated_at" TEXT, "created_by" TEXT);
CREATE TABLE "idea_protocol" ("id" TEXT PRIMARY KEY, "description" TEXT, "filename" TEXT);
CREATE TABLE "idea_reactant" ("id" TEXT PRIMARY KEY, "name" TEXT, "aliases" TEXT, "smiles" TEXT, "inchi" TEXT, "inchi_key" TEXT, "molecular_formula" TEXT, "molecular_weight" REAL, "notes" TEXT, "created_at" TEXT, "updated_at" TEXT, "created_by" TEXT);
CREATE TABLE "idea_reaction" ("id" TEXT PRIMARY KEY, "name" TEXT, "equation" TEXT, "smarts" TEXT, "reaction_type" TEXT, "notes" TEXT, "created_at" TEXT, "updated_at" TEXT, "created_by" TEXT);
CREATE TABLE "idea_sample" ("id" TEXT PRIMARY KEY, "name" TEXT, "experiment_id" TEXT, "strain_id" INTEGER, "replicate" INTEGER, "sample_type" TEXT, "parent_sample_id" TEXT, "storage_location" TEXT, "notes" TEXT, "created_at" TEXT, "updated_at" TEXT, "created_by" TEXT);
CREATE TABLE "idea_stoichiometry" ("id" INTEGER PRIMARY KEY, "idea_reaction_id" TEXT, "idea_reactant_id" TEXT, "coefficient" REAL, "role" TEXT, "notes" TEXT, "created_at" TEXT, "updated_at" TEXT, "created_by" TEXT);
CREATE TABLE "idea_strain" ("id" TEXT PRIMARY KEY, "long_name" TEXT, "short_name" TEXT, "parent_strain_id" TEXT);
CREATE TABLE "protein_parameter" ("id" TEXT PRIMARY KEY, "idea_protein_id" TEXT, "idea_mutant_id" TEXT, "label" TEXT, "value" TEXT, "unit" TEXT, "error" TEXT, "measurement_id" TEXT, "computation_id" TEXT, "idea_reaction_id" TEXT, "notes" TEXT);
CREATE TABLE "sample_parameter" ("id" INTEGER PRIMARY KEY, "sample_id" TEXT, "idea_reactant_id" TEXT, "idea_reaction_id" TEXT, "label" TEXT, "value" TEXT, "value_type" TEXT, "unit" TEXT, "created_at" TEXT, "updated_at" TEXT, "created_by" TEXT);
CREATE TABLE "sample_protein" ("id" INTEGER PRIMARY KEY, "sample_id" TEXT, "idea_protein_id" TEXT, "idea_mutant_id" TEXT, "created_at" TEXT, "updated_at" TEXT, "created_by" TEXT);
CREATE TABLE "sample_reactant" ("id" INTEGER PRIMARY KEY, "sample_id" TEXT, "idea_reactant_id" TEXT, "concentration" REAL, "concentration_unit" TEXT, "created_at" TEXT, "updated_at" TEXT, "created_by" TEXT);
CREATE TABLE "sample_reaction" ("id" INTEGER PRIMARY KEY, "sample_id" TEXT, "idea_reaction_id" TEXT, "is_primary" INTEGER, "created_at" TEXT, "updated_at" TEXT, "created_by" TEXT);
COMMIT;
